#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        printf("hello, I am child (pid: %d)\n", getpid());
        exit(0);
    } else if (pid > 0) {  // Parent process
        wait(NULL);  // Wait for child to finish
        printf("hello, I am parent of %d (pid: %d)\n", pid, getpid());
    }
    return 0;
}
